/*
 * A209830  Triangle of coefficients of polynomials u(n,x) jointly generated
 *          with A209831; see the Formula section.
 * https://oeis.org/A209830
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) = coefficient of x^{k} in u(r,x) where r is the row number
 *            satisfying r(r+1)/2 ≥ n, and k = n - (r-1)r/2 - 1 (0‑based). The
 *            coefficients are generated by u(n,x) = x*u(n-1,x) +
 *            (x+1)*v(n-1,x), v(n,x) = (x+1)*u(n-1,x) + 2x*v(n-1,x), with
 *            u(1,x)=v(1,x)=1. The recurrence for the coefficients is...
 * Range:     u8 n <= 24, u16 n <= 56, u32 n <= 56, u64 n <= 56, u128 n <= 56,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdlib.h>

seq_t a(idx_t n)
{
    /* Find the row r that contains index n.  The cumulative triangular
       number r(r+1)/2 is the number of terms up to row r. */
    idx_t r = 0;
    idx_t triangular = 0;
    while (triangular < n) {
        ++r;
        triangular += r;
    }
    /* Position inside the row (0‑based). */
    idx_t prev_triangular = triangular - r;
    idx_t pos = n - prev_triangular - 1;

    /* Special case: first row is just the constant 1. */
    if (r == 1) {
        return (seq_t)1;
    }

    /* Allocate two buffers large enough to hold the longest row needed. */
    size_t max_len = (size_t)r;
    seq_t *bufU[2];
    seq_t *bufV[2];
    bufU[0] = (seq_t *)calloc(max_len, sizeof(seq_t));
    bufV[0] = (seq_t *)calloc(max_len, sizeof(seq_t));
    bufU[1] = (seq_t *)calloc(max_len, sizeof(seq_t));
    bufV[1] = (seq_t *)calloc(max_len, sizeof(seq_t));

    /* Initialize row 1. */
    bufU[0][0] = (seq_t)1;
    bufV[0][0] = (seq_t)1;

    /* Current and previous buffer indices. */
    idx_t cur = 0;
    idx_t nxt = 1;

    /* Compute rows 2..r. */
    for (idx_t i = 2; i <= r; ++i) {
        for (idx_t k = 0; k < i; ++k) {
            seq_t u_val = 0;
            seq_t v_val = 0;

            if (k > 0) {
                u_val += bufU[cur][k - 1];
                u_val += bufV[cur][k - 1];

                v_val += bufU[cur][k - 1];
                seq_t two = bufV[cur][k - 1];
                two += two;          /* multiply by 2 */
                v_val += two;
            }
            if (k < i - 1) {
                u_val += bufV[cur][k];
                v_val += bufU[cur][k];
            }

            bufU[nxt][k] = u_val;
            bufV[nxt][k] = v_val;
        }
        /* Swap buffers for next iteration. */
        idx_t tmp = cur;
        cur = nxt;
        nxt = tmp;
    }

    /* The requested coefficient is in bufU[cur][pos]. */
    seq_t result = bufU[cur][pos];

    /* Free all allocated buffers. */
    free(bufU[0]);
    free(bufU[1]);
    free(bufV[0]);
    free(bufV[1]);

    return result;
}
